update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p061","body":"شوقِ وصلِ تمنا دکھانے کو کہاں\nاب جنوں دل کا لبھانے کو کہاں\n\nوہ شمعیں جو جلی رہ گئیں\nوقت ان کا بجھانے کو کہاں\n\nآج نئی امید نئی آرزو لیے ہم\nچلے ہیں قسمت آزمانے کو کہاں\n\nجو چلے منہ پھیر کے اور مڑ کے نہ دیکھے\nوہ گیا وہ کبھی لوٹ کے آنے کو کہاں\n\nسوچا کہ مٹا دیں سبھی حسرتوں کو ہم\nمگر ذکر تم کا دل سے جانے کو کہاں\n\nملیں تو لوٹ آئیں گی بہاریں احمد ؔ\nچلیں تو یاد بھی آئیں گے زمانے کو کہاں"},{"slug":"tum-p062","body":"دہر کی شب تاریکی  سحر انجام ہوتی\nجو شام زندگی کی تیری قربت میں تمام ہوتی\n\nکب تک ہوگا اے دل اس محبت پہ سوگوار\nجو اگر مل بھی جاتی تو ہرگز ناکام ہوتی"},{"slug":"tum-p063","body":"ہم نہیں وہ کشیدہ دل\nوہ ہم نشیں ، وہ ہم قدم\nوہ ہم اثر ، وہ مہرباں\nوہ کہکشاں وہ کوئی اور ہے\n\nوہ راہگزر جسے دیکھ کر\nچل دیے کئی ہم سفر\nوہ راہگزاں ، وہ راہبراں\nوہ فلاں فلاں وہ کوئی اور ہے\n\nجسے خود ہی خود کی تلاش ہے\nجسے خود ہی خود نہ مل سکے\nجو ہے گمشدہ وہ ہم ہی تو ہیں\nجو ہے رواں دواں وہ کوئی اور ہے\n\nہم تو ہیں ہی فقط فسانہ گو\nہم کہتے ہیں پورے اترتے نہیں\nہم  ہیں ملالِ دل  اور ہیں وبالِ جاں\nجو ہے اطمیناں وہ کوئی اور ہے\n\nجسے آپ کہتے تھے آشنا\nجسے آپ نے سمجھا رازداں\nوہ صبر کے گھونٹ پی مر گیا\nجو ہے ہم زباں وہ کوئی اور ہے"},{"slug":"tum-p064","body":"بےحساب غم دنیا خواہشوں کا بھار لیے\nلو چلے گئے ہم حسرتوں کا مزار لیے\n\nکسے معلوم اس وقت کس پناہ میں ہوں\nکسے خبر کہ بےخبر ہے کونسی قطار لیے\n\nہم دنیا میں رہتے خواب دیکھتے رہ گئے\nوہ دنیا جو کھڑی تھی ہاتھ میں تلوار لیے\n\nاے دل جسے معلوم نہ تھا زندگی کا مطلب\nتو کہاں تک آن پہنچا ہے آج غم یار لیے\n\nاٹھی جو شور سے نظر تو یہ جان پڑا\nکوئی اپنا نہ تھا یہاں تک کہ خار لیے\n\nہم زندگی کے اس کٹھن سفر میں احمد ؔ\nخزاں رسیدہ ہو گئے دلِ بہار لیے\n\nچلو کسی بہانے تمہیں یاد تو آئے ہم\nہم یہیں پڑے تھے گھڑی انتظار لیے"},{"slug":"tum-p065","body":"دل کی طویل وسعتوں میں ایک گھر تمنا کا تھا\nدغا کے ہزار راستوں میں ایک راستہ وفا کا تھا\n\nہجر کی تلخیوں کو جب ملی وصل کی مرہمیں\nتو جانا یہ جاناں اصل لطف ہی سزا کا تھا\n\nگزاردی فقط ایک ہی قفس میں زندگی ساری\nزمانے نے سکھایا یہ کہ زمانہ بےوفا کا تھا\n\nہم رہے تاعمر صحرا میں ، گھٹا آئی بھی تو کب\nفلک پہ ابر چھایا تھا اور وقت نزع کا تھا\n\nاے خدا یہ کیا کہ لاکھ حسرتیں اس میں\nیہ دل کہاں کا دل یہ دل تو اک گدا کا تھا\n\nکیا تو ، کیا میں ، کیا تیرا ملنا ، کیا بچھڑ جانا\nیہ سب اسی مصلحت تھی یہ فیصلہ خدا کا تھا\n\nسچ تھی تمہاری بات زخم بھر ہی جاتے ہیں\nمحبت درد وقتی تھا مگر یہ داغ سدا کا تھا\n\nمجھے اب یاد آیا یہ کہ تم تو بس یاد آئے ہو\nمیں اب سمجھا کہ تیرا زکر یہ سب ہوا کا تھا"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
